<?php
declare(strict_types=1);
require_once __DIR__.'/../config/config.php';
require_once __DIR__.'/../02_Gameplay/WorldService.php';
$pdo=db();if(!$pdo){fwrite(STDERR,"SKIP: database unavailable\n");exit(0);} $svc=new WorldService($pdo);$playerId=1;$snapshot=$svc->galaxySnapshot($playerId);if(!in_array($snapshot['state'],['ready','empty'],true))throw new RuntimeException('Unexpected Galaxy Map state.');if(!array_key_exists('galaxies',$snapshot)||!array_key_exists('sectors',$snapshot)||!array_key_exists('coordinate_scope',$snapshot))throw new RuntimeException('Incomplete Galaxy Map contract.');if($snapshot['state']==='ready'){if(!$snapshot['selected'])throw new RuntimeException('Ready map has no selected galaxy.');if(!$snapshot['scan_permission'])throw new RuntimeException('Authenticated commander lacks scan permission.');if(!str_starts_with((string)$snapshot['coordinate_scope'],'galaxy:'))throw new RuntimeException('Coordinate scope was not constrained to a galaxy.');foreach($snapshot['sectors'] as $sector){foreach(['system_count','discovered_system_count','planet_count','occupied_planet_count','danger_level'] as $key)if(!array_key_exists($key,$sector))throw new RuntimeException('Missing sector aggregate: '.$key);}}echo 'PASS: Galaxy Map visibility, sector distribution, coordinate scope, scan permission, and ownership contract verified'.PHP_EOL;
